fn pickR(p: { ...r }, q: { ...s }): { ...r, ...s }
  where r disjoint s = pickR(p, q);
fn apply(f: (a, b) -> { x: Int, y: Int }, g: (a, b) -> Int): Int = 0;
fn noX(p: { ...u }, q: { ...v }): Int where u lacks { y }, v lacks { x }
  = 0;
fn main(): Int = apply(fn(p: { x: Int }, q) => pickR(p, q), noX);
